<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.getElementById('item-type');const fields=document.querySelectorAll('.stock-only');const toggle=()=>{const service=type?.value==='service';fields.forEach(field=>field.classList.toggle('d-none',service));if(service)fields.forEach(field=>field.querySelectorAll('input').forEach(input=>input.value=0));};type?.addEventListener('change',toggle);toggle();});</script>
